import { ImportActionRequest, ImportActionResponse, } from './scheduler_migration.js';
export class SchedulerMigrationClientJSON {
    constructor(rpc) {
        this.rpc = rpc;
        this.ImportAction.bind(this);
    }
    ImportAction(request) {
        const data = ImportActionRequest.toJSON(request);
        const promise = this.rpc.request('devvit.plugin.scheduler.SchedulerMigration', 'ImportAction', 'application/json', data);
        return promise.then((data) => ImportActionResponse.fromJSON(data));
    }
}
export class SchedulerMigrationClientProtobuf {
    constructor(rpc) {
        this.rpc = rpc;
        this.ImportAction.bind(this);
    }
    ImportAction(request) {
        const data = ImportActionRequest.encode(request).finish();
        const promise = this.rpc.request('devvit.plugin.scheduler.SchedulerMigration', 'ImportAction', 'application/protobuf', data);
        return promise.then((data) => ImportActionResponse.decode(data));
    }
}
